class NavigationEnricher:
    """
    Génère automatiquement :

    - prerequisites
    - next_topics
    - related_topics

    ainsi que les relations du Knowledge Graph.
    """

    def enrich(self, families):

        for family in families:

            for chapter in family.chapters:

                topics = sorted(
                    chapter.topics,
                    key=lambda topic: topic.editorial_order,
                )

                self._link_sequence(topics)
                self._link_related(topics)

        return families

    # ==========================================================
    # Navigation pédagogique
    # ==========================================================

    def _link_sequence(
        self,
        topics: list[Topic],
    ):

        for index, topic in enumerate(topics):

            # --------------------------------------------------

            if index > 0:

                previous = topics[index - 1]

                if previous.id not in topic.prerequisites:

                    topic.prerequisites.append(previous.id)

                topic.add_relation(
                    target=previous.id,
                    relation_type="prerequisite",
                    score=1.0,
                    source="NavigationEnricher",
                )

            # --------------------------------------------------

            if index < len(topics) - 1:

                nxt = topics[index + 1]

                if nxt.id not in topic.next_topics:

                    topic.next_topics.append(nxt.id)

                topic.add_relation(
                    target=nxt.id,
                    relation_type="next",
                    score=1.0,
                    source="NavigationEnricher",
                )

    # ==========================================================
    # Related
    # ==========================================================

    def _link_related(
        self,
        topics: list[Topic],
    ):

        for topic in topics:

            for other in topics:

                if other.id == topic.id:
                    continue

                if other.id not in topic.related_topics:

                    topic.related_topics.append(other.id)

                topic.add_relation(
                    target=other.id,
                    relation_type="related",
                    score=0.60,
                    source="NavigationEnricher",
                )

from collections import deque

from v2.knowledge.engine.graph_engine import GraphEngine


class GraphTraversal:
    """
    Algorithmes de parcours du Knowledge Graph.
    """

    def __init__(
        self,
        engine: GraphEngine,
    ):
        self.engine = engine

    # ==========================================================
    # Reachable
    # ==========================================================

    def reachable(
        self,
        topic_id: str,
        max_depth: int = 2,
    ) -> list[str]:

        visited = {topic_id}

        queue = deque()

        queue.append((topic_id, 0))

        result = []

        while queue:

            current, depth = queue.popleft()

            if depth >= max_depth:
                continue

            for neighbor in self.engine.neighbors(current):

                if neighbor.id in visited:
                    continue

                visited.add(neighbor.id)

                result.append(neighbor.id)

                queue.append((neighbor.id, depth + 1))

        return result

    # ==========================================================
    # Shortest path
    # ==========================================================

    def shortest_path(
        self,
        source: str,
        target: str,
    ) -> list[str]:

        if source == target:
            return [source]

        visited = {source}

        queue = deque()

        queue.append((source, [source]))

        while queue:

            current, path = queue.popleft()

            for neighbor in self.engine.neighbors(current):

                if neighbor.id in visited:
                    continue

                new_path = path + [neighbor.id]

                if neighbor.id == target:
                    return new_path

                visited.add(neighbor.id)

                queue.append((neighbor.id, new_path))

        return []

